// Shader by @RobinsSecret on TwT

// Inspired by the work from Iñigo Quiles
// https://iquilezles.org/articles/distfunctions2d/

float dot2(in vec2 v ) { return dot(v,v); }

float sdCircle(vec2 p, float r){
    return length(p) - r;
}

float sdBox(vec2 p, vec2 b){
    vec2 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

float sdTrapezoid( in vec2 p, in float r1, float r2, float he )
{
    vec2 k1 = vec2(r2,he);
    vec2 k2 = vec2(r2-r1,2.0*he);

	p.x = abs(p.x);
    vec2 ca = vec2(max(0.0,p.x-((p.y<0.0)?r1:r2)), abs(p.y)-he);
    vec2 cb = p - k1 + k2*clamp( dot(k1-p,k2)/dot2(k2), 0.0, 1.0 );

    float s = (cb.x < 0.0 && ca.y < 0.0) ? -1.0 : 1.0;

    return s*sqrt( min(dot2(ca),dot2(cb)) );
}

vec3 drawSun(vec2 uv, float radius, vec3 sunColor, vec3 skyColor){
    vec3 col = vec3(0.0);

    float d = sdCircle(uv, radius);
    if(d < 0.0){
        col = sunColor;
    } else{
        col = skyColor;
    }
    col *= 1.0 - exp(-10.0*abs(d));
    col *= 0.8 + 0.2*cos(150.0*d);
    col = mix(col, vec3(1.0), 1.0 - smoothstep(0.0, 0.01, abs(d)));

    return col;
}

vec3 drawMountain(vec2 mountPos, vec3 col, float r1, float r2, float h, vec3 color){
    float d = sdTrapezoid(mountPos, r1, r2, h);
    col *= 1.0 - exp(-8.0*abs(d));
    if(d < 0.0){
        col = color;
        col *= 0.8 + 0.2*cos(140.0*d);
        col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.015,abs(d)) );
        col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.005,abs(d)) );
    }
    return col;
}

vec3 drawCloud(vec2 cloudPos, vec3 col, vec2 cloudSize, vec3 cloudColor){
    float d = sdBox(cloudPos, cloudSize);
    col *= 1.0 - exp(-20.0*abs(d));
    if (d < 0.0){
        col = cloudColor;
        col *= 0.8 + 0.2*cos(140.0*d);
        col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.015,abs(d)) );
        col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.005,abs(d)) );
    }

    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0.0);    


    // draw sun and sky
    vec3 sunColor = vec3(1.2, 0.4, 0.4);
    vec3 skyColor = vec3(1.0, 0.97, 0.89);
    col = drawSun(uv, 0.4, sunColor, skyColor);

    // draw mountains
    vec2 mountPos = vec2(uv.x + 1.4, uv.y + 0.8); 
    vec3 mountainColor = vec3(0.53,0.41,0.35);
    col = drawMountain(mountPos, col, 1.1, 0.7, 1.0, mountainColor);
    mountPos = vec2(uv.x - 1.4, uv.y + 0.8); 
    col = drawMountain(mountPos, col, 1.1, 0.7, 1.0, mountainColor);
    mountPos = vec2(uv.x-0.7, uv.y + 1.0);
    col = drawMountain(mountPos, col, 0.6, 0.4, 0.5, mountainColor);
    mountPos = vec2(uv.x+0.7, uv.y + 1.0);
    col = drawMountain(mountPos, col, 0.6, 0.4, 0.5, mountainColor);

    // draw clouds
    vec3 cloudColor = vec3(1.0, 0.99, 0.95);

    vec2 varyDist = vec2(sin(iTime/6.0)/2.0, 0);

    vec2 cloudPos = vec2(uv.x + 1.0, uv.y - 0.3) - varyDist;
    col = drawCloud(cloudPos, col, vec2(0.4, 0.2), cloudColor);

    cloudPos = cloudPos - vec2(0.3,0.2);
    col = drawCloud(cloudPos, col, vec2(0.2, 0.15), cloudColor);


    cloudPos = vec2(uv.x - 1.0, uv.y + 0.5) - varyDist;
    col = drawCloud(cloudPos, col, vec2(0.5, 0.2), cloudColor);

    cloudPos = cloudPos - vec2(0.4, - 0.2);
    col = drawCloud(cloudPos, col, vec2(0.3, 0.12), cloudColor);


    fragColor = vec4(col, 1.0);
}
